import csv, json, html, math
from pathlib import Path
from collections import Counter, defaultdict

DATA_PATH = Path('/app/benchmark/data.csv')
OUT_PATH = Path('/app/output/final_report.html')
rows = list(csv.DictReader(DATA_PATH.open(newline='', encoding='utf-8')))
for r in rows:
    r['Year'] = int(r['Year'])
rows.sort(key=lambda r: r['Year'])

def split_names(composer):
    return [name.strip() for name in composer.split(',')]

# Enrich rows
seen = set()
for r in rows:
    r['Names'] = split_names(r['Composer'])
    r['Decade'] = (r['Year'] // 10) * 10
    r['IsRepeatCeremony'] = any(n in seen for n in r['Names'])
    r['NewNames'] = [n for n in r['Names'] if n not in seen]
    seen.update(r['Names'])

all_names = [n for r in rows for n in r['Names']]
composer_counts = Counter(all_names)
years_by = defaultdict(list)
films_by = defaultdict(list)
for r in rows:
    for n in r['Names']:
        years_by[n].append(r['Year'])
        films_by[n].append(r['Film'])

top_composers = sorted(composer_counts.items(), key=lambda x: (-x[1], min(years_by[x[0]]), x[0]))
repeat_composers = [(n, c) for n, c in top_composers if c > 1]

# KPIs
total_ceremonies = len(rows)
unique_composers = len(composer_counts)
unique_films = len(set(r['Film'] for r in rows))
max_wins = max(composer_counts.values())
max_winners = [n for n, c in composer_counts.items() if c == max_wins]
repeat_ceremonies = sum(r['IsRepeatCeremony'] for r in rows)
repeat_rate = repeat_ceremonies / total_ceremonies
collab_ceremonies = sum(1 for r in rows if len(r['Names']) > 1)

# Decade stats
decade_stats = []
for dec in range(1930, 2030, 10):
    dr = [r for r in rows if r['Decade'] == dec]
    if not dr:
        continue
    names = {n for r in dr for n in r['Names']}
    wins = sum(len(r['Names']) for r in dr)
    repeat = sum(r['IsRepeatCeremony'] for r in dr)
    top_in_dec = Counter(n for r in dr for n in r['Names']).most_common(3)
    decade_stats.append({
        'decade': f'{dec}s',
        'start': dec,
        'ceremonies': len(dr),
        'unique_winners': len(names),
        'individual_awardees': wins,
        'repeat_ceremonies': repeat,
        'repeat_rate': repeat / len(dr),
        'collab_ceremonies': sum(1 for r in dr if len(r['Names']) > 1),
        'top': top_in_dec,
    })
max_unique_decades = [d for d in decade_stats if d['unique_winners'] == max(x['unique_winners'] for x in decade_stats)]
most_unique_label = ', '.join(d['decade'] for d in max_unique_decades)

# Eras derived from Year only (source has no Era/Style columns)
eras = [
    ('Golden Age consolidation', 1934, 1959, 'Studio-era prestige, orchestral classicism, and early recurrence by Steiner, Tiomkin, Newman, Rózsa, and Waxman.'),
    ('Silver Age transition', 1960, 1979, 'Roadshow epics give way to pop-inflected, auteur-era, and blockbuster signals, from Jarre to Williams.'),
    ('Modern expansion', 1980, 1999, 'The field broadens across synth idioms, animated musicals, global co-winners, prestige drama, and event cinema.'),
    ('Contemporary globalization', 2000, 2026, 'A more international and hybrid landscape, with late-career returns and an unusually concentrated Göransson run in the 2020s.'),
]
era_stats = []
for label, start, end, note in eras:
    er = [r for r in rows if start <= r['Year'] <= end]
    names = [n for r in er for n in r['Names']]
    cnt = Counter(names)
    era_seen = set(); repeat_within = 0
    for r in er:
        if any(n in era_seen for n in r['Names']):
            repeat_within += 1
        era_seen.update(r['Names'])
    era_stats.append({
        'label': label,
        'start': start,
        'end': end,
        'note': note,
        'ceremonies': len(er),
        'unique_winners': len(set(names)),
        'repeat_within': repeat_within,
        'collab_ceremonies': sum(1 for r in er if len(r['Names']) > 1),
        'top': cnt.most_common(5),
    })

# Gaps and streaks
gaps = []
for n, ys in years_by.items():
    ys = sorted(ys)
    for a, b in zip(ys, ys[1:]):
        gaps.append((b - a, n, a, b))
gaps.sort(reverse=True)
longest_gap = gaps[0]

consecutive_repeat_sequences = []
current = []
for r in rows:
    if r['IsRepeatCeremony']:
        current.append(r)
    else:
        if len(current) > 1:
            consecutive_repeat_sequences.append(current)
        current = []
if len(current) > 1:
    consecutive_repeat_sequences.append(current)
longest_repeat_run = max(consecutive_repeat_sequences, key=len)

duplicate_films = [(film, c) for film, c in Counter(r['Film'] for r in rows).items() if c > 1]
first_winners = len([r for r in rows if not r['IsRepeatCeremony']])

# Helper for SVG charts
colors = {
    'ink': '#182033',
    'muted': '#64748b',
    'blue': '#2867b2',
    'blue2': '#5ba4e5',
    'gold': '#d89a28',
    'gold2': '#f3c05a',
    'green': '#2f8f83',
    'red': '#b94b57',
    'paper': '#fbf7ef',
}

def esc(x):
    return html.escape(str(x), quote=True)

def bar_chart_top(top_items):
    width, height = 920, 430
    margin_l, margin_r, margin_t, margin_b = 210, 35, 25, 45
    chart_w = width - margin_l - margin_r
    row_h = 28
    maxv = max(v for _, v in top_items)
    svg = [f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="Top composers by wins">']
    svg.append(f'<rect width="{width}" height="{height}" fill="transparent"/>')
    for i, (name, val) in enumerate(top_items):
        y = margin_t + i * row_h
        bar_w = chart_w * val / maxv
        fill = colors['gold'] if val == maxv else colors['blue'] if val >= 3 else colors['blue2']
        svg.append(f'<text x="{margin_l-12}" y="{y+18}" text-anchor="end" class="svg-label">{esc(name)}</text>')
        svg.append(f'<rect x="{margin_l}" y="{y+5}" width="{bar_w:.1f}" height="18" rx="9" fill="{fill}"><title>{esc(name)}: {val} wins ({", ".join(map(str, years_by[name]))})</title></rect>')
        svg.append(f'<text x="{margin_l+bar_w+10}" y="{y+18}" class="svg-value">{val}</text>')
    # axis
    y_axis = margin_t + len(top_items)*row_h + 10
    for tick in range(1, maxv+1):
        x = margin_l + chart_w * tick / maxv
        svg.append(f'<line x1="{x:.1f}" y1="{margin_t}" x2="{x:.1f}" y2="{y_axis}" stroke="#e5e7eb" stroke-width="1"/>')
        svg.append(f'<text x="{x:.1f}" y="{height-16}" text-anchor="middle" class="svg-tick">{tick}</text>')
    svg.append('</svg>')
    return ''.join(svg)

def decade_chart():
    width, height = 980, 430
    ml, mr, mt, mb = 64, 32, 36, 78
    cw, ch = width-ml-mr, height-mt-mb
    max_unique = max(d['unique_winners'] for d in decade_stats)
    max_cer = max(d['ceremonies'] for d in decade_stats)
    band = cw / len(decade_stats)
    barw = min(48, band * 0.48)
    pts = []
    svg = [f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="Decade chart: unique winners and repeat rates">']
    svg.append('<rect width="100%" height="100%" fill="transparent"/>')
    for t in range(0, max_unique+1, 3):
        y = mt + ch - ch*t/max_unique
        svg.append(f'<line x1="{ml}" y1="{y:.1f}" x2="{width-mr}" y2="{y:.1f}" stroke="#e8e1d4"/>')
        svg.append(f'<text x="{ml-10}" y="{y+4:.1f}" text-anchor="end" class="svg-tick">{t}</text>')
    for i,d in enumerate(decade_stats):
        x = ml + band*i + band/2
        h = ch*d['unique_winners']/max_unique
        y = mt + ch - h
        fill = colors['gold'] if d in max_unique_decades else colors['blue']
        svg.append(f'<rect x="{x-barw/2:.1f}" y="{y:.1f}" width="{barw}" height="{h:.1f}" rx="8" fill="{fill}"><title>{d["decade"]}: {d["unique_winners"]} unique composers; {d["repeat_ceremonies"]}/{d["ceremonies"]} repeat-winner ceremonies</title></rect>')
        svg.append(f'<text x="{x:.1f}" y="{y-8:.1f}" text-anchor="middle" class="svg-value">{d["unique_winners"]}</text>')
        svg.append(f'<text x="{x:.1f}" y="{height-42}" text-anchor="middle" class="svg-tick">{d["decade"]}</text>')
        ry = mt + ch - ch*d['repeat_rate']
        pts.append((x, ry, d))
    # repeat-rate line scaled to 0-100%
    path = ' '.join(('M' if i==0 else 'L') + f' {x:.1f} {y:.1f}' for i,(x,y,_) in enumerate(pts))
    svg.append(f'<path d="{path}" fill="none" stroke="{colors["red"]}" stroke-width="3"/>')
    for x,y,d in pts:
        svg.append(f'<circle cx="{x:.1f}" cy="{y:.1f}" r="5" fill="{colors["red"]}"><title>{d["decade"]}: repeat-winner rate {d["repeat_rate"]*100:.1f}%</title></circle>')
    svg.append(f'<text x="{ml}" y="22" class="svg-note">Bars: unique winning composers · Red line: ceremonies won by a prior winner</text>')
    svg.append('</svg>')
    return ''.join(svg)

def era_chart():
    width, height = 980, 330
    ml, mr, mt, mb = 52, 28, 26, 60
    cw, ch = width-ml-mr, height-mt-mb
    maxu = max(e['unique_winners'] for e in era_stats)
    band = cw/len(era_stats)
    svg = [f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="Era comparison chart">']
    for i,e in enumerate(era_stats):
        x = ml + i*band + 28
        w = band - 56
        h = ch*e['unique_winners']/maxu
        y = mt + ch - h
        svg.append(f'<rect x="{x:.1f}" y="{y:.1f}" width="{w:.1f}" height="{h:.1f}" rx="14" fill="{colors["green"]}"><title>{esc(e["label"])}: {e["unique_winners"]} unique composers across {e["ceremonies"]} ceremonies</title></rect>')
        svg.append(f'<text x="{x+w/2:.1f}" y="{y-10:.1f}" text-anchor="middle" class="svg-value">{e["unique_winners"]}</text>')
        svg.append(f'<text x="{x+w/2:.1f}" y="{height-38}" text-anchor="middle" class="svg-tick">{e["start"]}–{e["end"]}</text>')
        svg.append(f'<text x="{x+w/2:.1f}" y="{height-18}" text-anchor="middle" class="svg-tick small">{esc(e["label"].split()[0])}</text>')
    svg.append(f'<text x="{ml}" y="18" class="svg-note">Unique individual composers by derived historical era</text>')
    svg.append('</svg>')
    return ''.join(svg)

def timeline_svg():
    width, height = 1120, 270
    ml, mr, mt = 55, 35, 42
    cw = width - ml - mr
    y1, y2 = 86, 186
    miny, maxy = rows[0]['Year'], rows[-1]['Year']
    def x(year): return ml + cw*(year-miny)/(maxy-miny)
    svg = [f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="Timeline of Oscar-winning scores">']
    svg.append(f'<line x1="{ml}" y1="{y1}" x2="{width-mr}" y2="{y1}" stroke="#c8bda9" stroke-width="2"/>')
    svg.append(f'<line x1="{ml}" y1="{y2}" x2="{width-mr}" y2="{y2}" stroke="#c8bda9" stroke-width="2"/>')
    for yr in range(1940, 2030, 10):
        xx=x(yr)
        svg.append(f'<line x1="{xx:.1f}" y1="62" x2="{xx:.1f}" y2="208" stroke="#eee5d7"/>')
        svg.append(f'<text x="{xx:.1f}" y="236" text-anchor="middle" class="svg-tick">{yr}</text>')
    for r in rows:
        xx=x(r['Year'])
        yy = y1 if not r['IsRepeatCeremony'] else y2
        fill = colors['blue'] if not r['IsRepeatCeremony'] else colors['red']
        radius = 4.2 + min(4, len(r['Names'])-1)
        title = f"{r['Year']} — {r['Film']} — {r['Composer']}" + (" (prior winner present)" if r['IsRepeatCeremony'] else " (all first-time winners)")
        svg.append(f'<circle cx="{xx:.1f}" cy="{yy}" r="{radius}" fill="{fill}" opacity="0.9"><title>{esc(title)}</title></circle>')
    svg.append(f'<text x="{ml}" y="28" class="svg-note">Top row: first-time-winning credited composers · Bottom row: at least one prior Oscar winner credited</text>')
    svg.append(f'<text x="{ml}" y="{y1-14}" class="svg-label">First-time ceremonies</text>')
    svg.append(f'<text x="{ml}" y="{y2-14}" class="svg-label">Repeat-winner ceremonies</text>')
    svg.append('</svg>')
    return ''.join(svg)

# Data for embedded JS table filtering
rows_for_json = [{
    'Year': r['Year'], 'Film': r['Film'], 'Composer': r['Composer'], 'Decade': f"{r['Decade']}s", 'Repeat': 'Yes' if r['IsRepeatCeremony'] else 'No'
} for r in rows]

# Build tables
composer_rows = []
for rank, (name, count) in enumerate(top_composers, 1):
    if count < 2: continue
    composer_rows.append(f'<tr><td>{rank}</td><td>{esc(name)}</td><td><strong>{count}</strong></td><td>{esc(", ".join(map(str, years_by[name])))}</td><td>{esc("; ".join(films_by[name]))}</td></tr>')

decade_rows = []
for d in decade_stats:
    top_txt = ', '.join(f'{n} ({c})' for n,c in d['top'])
    decade_rows.append(f'<tr><td>{d["decade"]}</td><td>{d["ceremonies"]}</td><td>{d["unique_winners"]}</td><td>{d["repeat_ceremonies"]}</td><td>{d["repeat_rate"]*100:.1f}%</td><td>{d["collab_ceremonies"]}</td><td>{esc(top_txt)}</td></tr>')

era_cards = []
for e in era_stats:
    leaders = ', '.join(f'{n} ({c})' for n,c in e['top'] if c > 1) or 'No multi-win leader within era'
    era_cards.append(f'''
      <article class="era-card">
        <div class="era-years">{e['start']}–{e['end']}</div>
        <h3>{esc(e['label'])}</h3>
        <p>{esc(e['note'])}</p>
        <dl>
          <div><dt>Ceremonies</dt><dd>{e['ceremonies']}</dd></div>
          <div><dt>Unique composers</dt><dd>{e['unique_winners']}</dd></div>
          <div><dt>Repeat ceremonies within era</dt><dd>{e['repeat_within']}</dd></div>
          <div><dt>Shared-credit ceremonies</dt><dd>{e['collab_ceremonies']}</dd></div>
        </dl>
        <p class="mini"><strong>Era leaders:</strong> {esc(leaders)}</p>
      </article>''')

milestone_items = [
    f'<li><strong>First listed winner:</strong> Louis Silvers for <em>One Night of Love</em> in 1934.</li>',
    f'<li><strong>Most wins:</strong> {", ".join(esc(n) for n in sorted(max_winners))}, each with {max_wins} wins in the dataset.</li>',
    f'<li><strong>Longest gap between wins:</strong> {esc(longest_gap[1])}, {longest_gap[0]} years between {longest_gap[2]} and {longest_gap[3]}.</li>',
    f'<li><strong>Longest run of repeat-winner ceremonies:</strong> {len(longest_repeat_run)} ceremonies from {longest_repeat_run[0]["Year"]} through {longest_repeat_run[-1]["Year"]}.</li>',
    f'<li><strong>Most recent winner:</strong> Ludwig Göransson for <em>Sinners</em> in 2026.</li>',
    f'<li><strong>Data limitation:</strong> age is not present in <code>data.csv</code>, so youngest/oldest winner cannot be determined without external data.</li>',
]
if duplicate_films:
    milestone_items.append('<li><strong>Film-title anomaly:</strong> ' + '; '.join(f'<em>{esc(f)}</em> appears {c} times' for f,c in duplicate_films) + '. This is reported as-is from <code>data.csv</code>.</li>')

